'use client';

import { useState, useMemo, useCallback } from 'react';
import { ProductCard } from './ProductCard';

interface Product {
  id: string;
  name: string;
  price: number;
  category: string;
  rating: number;
  inStock: boolean;
}

interface Review {
  id: string;
  productId: string;
  text: string;
  rating: number;
  author: string;
}

interface Props {
  products: Product[];
  reviews: Review[];
}

export function ProductList({ products, reviews }: Props) {
  const [cart, setCart] = useState<Set<string>>(new Set());
  const [filter, setFilter] = useState('');
  const [sortBy, setSortBy] = useState<'price' | 'rating'>('price');

  // Memoize review count map to avoid O(n²) lookup - compute once
  const reviewCountMap = useMemo(() => {
    const map = new Map<string, number>();
    for (const review of reviews) {
      map.set(review.productId, (map.get(review.productId) || 0) + 1);
    }
    return map;
  }, [reviews]);

  // Memoize filtered and sorted products
  const filteredProducts = useMemo(() => {
    return products
      .filter(p => p.name.toLowerCase().includes(filter.toLowerCase()))
      .filter(p => p.inStock)
      .sort((a, b) => sortBy === 'price' ? a.price - b.price : b.rating - a.rating);
  }, [products, filter, sortBy]);

  // Memoize callback to prevent unnecessary re-renders of ProductCard
  const handleAddToCart = useCallback((productId: string) => {
    setCart(prev => new Set(prev).add(productId));
  }, []);

