// src/app/api/products/route.ts
import { NextRequest, NextResponse } from 'next/server';
import {
  fetchUserFromService,
  fetchProductsFromService,
  logAnalyticsToService,
} from '@/services/api-client';

// Enable caching with 60 second revalidation instead of force-dynamic
export const revalidate = 60;

export async function GET(request: NextRequest) {
  // Parallelize independent API calls
  const [user, products] = await Promise.all([
    fetchUserFromService(),
    fetchProductsFromService(),
  ]);

  // Fire-and-forget analytics - don't await to avoid blocking response
  logAnalyticsToService({ userId: user.id, action: 'view_products', count: products.length }).catch(() => {
    // Silently handle analytics failures - they shouldn't affect the response
  });

  return NextResponse.json({ products });
}

